import { usePrimaryArtistForCurrentUser } from '@app/web-player/backstage/use-primary-artist-for-current-user';
import { useFollowArtist } from '@app/web-player/artists/requests/use-follow-artist';
import { useUnfollowArtist } from '@app/web-player/artists/requests/use-unfollow-artist';
import { Likeable } from '@app/web-player/library/likeable';
import { useAddItemsToLibrary } from '@app/web-player/library/requests/use-add-items-to-library';
import { useRemoveItemsFromLibrary } from '@app/web-player/library/requests/use-remove-items-from-library';
import { useLibraryStore } from '@app/web-player/library/state/likes-store';
import { useLikeTrack } from '@app/web-player/tracks/hooks/use-like-track';
import { useUnlikeTrack } from '@app/web-player/tracks/hooks/use-unlike-track';
import { useAuthClickCapture } from '@app/web-player/use-auth-click-capture';
import { useIsOffline } from '@app/web-player/use-is-offline';
import { IconButton, IconButtonProps } from '@ui/buttons/icon-button';
import { FavoriteIcon } from '@ui/icons/material/Favorite';
import { FavoriteBorderIcon } from '@ui/icons/material/FavoriteBorder';

interface LikeIconButtonProps
  extends Omit<IconButtonProps, 'children' | 'disabled' | 'onClick'> {
  likeable: Likeable;
}
export function LikeIconButton({
  likeable,
  size = 'sm',
  ...buttonProps
}: LikeIconButtonProps) {
  const isArtist = likeable.model_type === 'artist';
  const actionType = isArtist ? 'follow' : 'like';
  const authHandler = useAuthClickCapture(actionType);
  const addToLibrary = useAddItemsToLibrary();
  const removeFromLibrary = useRemoveItemsFromLibrary();
  const followArtist = useFollowArtist();
  const unfollowArtist = useUnfollowArtist();
  const likeTrack = useLikeTrack();
  const unlikeTrack = useUnlikeTrack();
  const isLiked = useLibraryStore(s => s.has(likeable));
  const isOffline = useIsOffline();
  const primaryArtist = usePrimaryArtistForCurrentUser();
  const isTrack = likeable.model_type === 'track';
  const isOwnArtist = isArtist && primaryArtist?.id === likeable.id;

  const getIsLoading = () => {
    if (isArtist) {
      return followArtist.isPending || unfollowArtist.isPending;
    }
    if (isTrack) {
      return likeTrack.isPending || unlikeTrack.isPending;
    }
    return addToLibrary.isPending || removeFromLibrary.isPending;
  };

  const isLoading = getIsLoading();
  const isDisabled = isLoading || isOffline;

  if (isOwnArtist) {
    return null;
  }

  const handleAdd = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isArtist) {
      followArtist.mutate({artistId: likeable.id});
    } else if (isTrack) {
      likeTrack.mutate({trackId: likeable.id});
    } else {
      addToLibrary.mutate({likeables: [likeable]});
    }
  };

  const handleRemove = (e: React.MouseEvent) => {
    e.stopPropagation();
    if (isArtist) {
      unfollowArtist.mutate({artistId: likeable.id});
    } else if (isTrack) {
      unlikeTrack.mutate({trackId: likeable.id});
    } else {
      removeFromLibrary.mutate({likeables: [likeable]});
    }
  };

  if (isLiked) {
    return (
      <IconButton
        {...buttonProps}
        size={size}
        color="primary"
        disabled={isDisabled}
        onClickCapture={authHandler}
        onClick={handleRemove}
      >
        <FavoriteIcon />
      </IconButton>
    );
  }
  return (
    <IconButton
      {...buttonProps}
      size={size}
      disabled={isDisabled}
      onClickCapture={authHandler}
      onClick={handleAdd}
    >
      <FavoriteBorderIcon />
    </IconButton>
  );
}
